// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;
    function setUp() public { c = new Private_Bank(address(new Log())); }

    function testFuzz_property(uint96 depositAmount, uint96 cashOutAmount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(new Log()));
        uint256 deposit = bound(uint256(depositAmount), 1.01 ether, 1000 ether);
        // cash out strictly less than the deposit (but more than zero) so the
        // remaining balance must still be nonzero under correct accounting
        uint256 am = bound(uint256(cashOutAmount), 1, deposit - 1);

        vm.deal(actor, deposit);
        vm.prank(actor);
        c.Deposit{value: deposit}();
        uint256 before = c.balances(actor);

        vm.prank(actor);
        c.CashOut(am);

        // General rule: an exact withdrawal of am leaves balances[actor] == before - am.
        assertTrue(c.balances(actor) == before - am, "balance must decrease by exactly am");
    }
}
